//! LZO1X reference vectors generated with the original LZO C library
//! (`lzo1x_1` and `lzo1x_999`) as vendored and used by QNX's `mkifs`.
//!
//! Provenance: deterministic pseudorandom buffers and structured cases
//! were fed to thin development-only CLI wrappers around
//! `lzo1x_1_compress` and `lzo1x_999_compress` (each preceded by
//! `lzo_init()`) and round-tripped through the reference decoder at
//! generation time. Sources are capped at 4 KiB to keep the fixture
//! committable; the vectors are captured data, not code.

/// One source buffer with its reference-compressed blocks.
pub struct LzoVector {
    /// Human readable case name.
    pub name: &'static str,
    /// Uncompressed bytes as hex.
    pub source: &'static str,
    /// `(compressor, compressed bytes as hex)` pairs.
    pub blocks: &'static [(&'static str, &'static str)],
}

